package net.imadz.codegen.scaffolding.cqrs

import java.nio.file.{Files, Path, Paths}
import scala.sys.process._
import scala.util.Try

/** 生成器指纹标识（EP_GenerationTime_Code_Anchors §19.4「生成器版本载体」·2026-09-24 用户令收尾全清）。
  *
  * 语义：`@generated by CodegenMain:<generatorVersion>`——**生成器版本＝宿主仓库（backend-codegen）
  * 生成时刻的 git commit 短号**。为什么是它：生成器不是发布制品（无 semver），其「版本」的唯一
  * 客观真源就是代码库提交——同 commit ⇒ 同生成逻辑 ⇒ 可复现；「同一知识两个生成器版本产出不同代码」
  * 由此可对账（G 的第二个参数落地）。
  *
  * 纪律：
  *   - **不改（零行为变化）**：commit 号入文件头**不参与任何比对**（gen_manifest 指纹判据只看
  *     `@generated by` 行前缀·见 `WriteTerritory.FingerprintMark`）——KEEP/COVER 判定不受影响。
  *   - **默认可回退**：未提供显式版本时，git 不可用仍回退为日期（旧行为）。
  *   - **显式 pin**：-Dcodegen.generatorVersion=<token> 不探测 git，也不取日期。
  *     -Dcodegen.noGit=true 必须配合法 pin；noGit 只接受精确的 true/false。
  *     token 为 1–128 个 ASCII 字符，首字符字母/数字，其余为字母/数字或 +._/-；不 trim。
  *   - **一次生成一个值**（懒缓存）：全产物一致（与 knowledgeRelease 同纪律）；
  *     value 每次仍校验当前属性，不能因缓存已初始化而忽略非法配置。
  */
object GeneratorVersion {
  private lazy val resolved: String =
    resolve(sys.props, () => detectGitCommit(), () => java.time.LocalDate.now().toString)

  /** 生成器版本串（显式 pin；否则 git 短号·缺时日期）。公开 API 形状不变。 */
  def value: String = {
    validateProperties(sys.props)
    resolved
  }

  /** Pure preflight seam. The production caller and value both use sys.props. */
  private[codegen] def validateProperties(
      properties: scala.collection.Map[String, String]
  ): Option[String] = {
    val noGit = properties.get("codegen.noGit") match {
      case None | Some("false") => false
      case Some("true") => true
      case _ => throw new IllegalArgumentException("codegen.noGit must be exactly true or false")
    }
    val pin = properties.get("codegen.generatorVersion")
    pin.foreach { token =>
      if (token == null || !token.matches("[A-Za-z0-9][A-Za-z0-9+._/-]{0,127}"))
        throw new IllegalArgumentException(
          "codegen.generatorVersion must be a 1-128 character ASCII token: alphanumeric first, then alphanumeric or +._/- (no whitespace)"
        )
    }
    if (noGit && pin.isEmpty)
      throw new IllegalArgumentException("codegen.noGit=true requires an explicit codegen.generatorVersion pin")
    pin
  }

  /** Lazy providers make pin/noGit tests incapable of invoking a real git process. */
  private[codegen] def resolve(
      properties: scala.collection.Map[String, String],
      gitCommit: () => Option[String],
      fallbackDate: () => String
  ): String =
    validateProperties(properties).getOrElse(gitCommit().getOrElse(fallbackDate()))

  /** 从 CWD 起向上找 .git，读 HEAD 短号。失败＝None（调用方回退）。 */
  private def detectGitCommit(): Option[String] =
    Try {
      var dir: Path = Paths.get("").toAbsolutePath
      var found: Path = null
      var i = 0
      while (dir != null && i < 10) {
        if (Files.isDirectory(dir.resolve(".git"))) { found = dir; i = 10 }
        else { dir = dir.getParent; i += 1 }
      }
      if (found == null) None
      else {
        val out = Process(Seq("git", "rev-parse", "--short", "HEAD"), found.toFile).!!.trim
        if (out.nonEmpty && out.length <= 16 && out.forall(c => c.isLetterOrDigit)) Some(out) else None
      }
    }.toOption.flatten
}
